def build_agent(sandbox):
    # Create main hull with sufficient height to clear pillars and stay buoyant
    hull = sandbox.add_beam(x=5.0, y=1.94, width=2.0, height=1.0, density=100.0)

    # Create 4 paddles for propulsion, positioned at the back of the hull
    for i in range(4):
        x = 5.0 - 0.5 - i * 0.5  # Position to the left of the hull
        y = 1.94
        paddle = sandbox.add_beam(x, y, width=0.5, height=0.5, density=100.0)
        sandbox.add_joint(hull, paddle, (x, y), type='rigid')

    return hull

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    if front_x >= target_x + 0.1:
        # Stop the vehicle
        return

    # Apply thrust every 18 steps, distributing force across multiple paddles
    if step_count % 18 == 0:
        # Apply force to all bodies except the hull (paddles)
        for body in sandbox.bodies:
            if body != agent_body:
                # Adjust thrust based on velocity to prevent over-thrusting
                vx = body.linearVelocity.x
                if vx > 1.8:
                    thrust = 520.0 * 0.1
                elif vx > 1.0:
                    thrust = 520.0 * 0.4
                else:
                    thrust = 520.0
                # Apply force in the positive x-direction for propulsion
                sandbox.apply_force(body, thrust, 0.0, step_count=step_count)
